package com.axplatform.sheet;
import com.axplatform.common.Problem;
import java.util.*;
import org.junit.jupiter.api.Test;
import static org.assertj.core.api.Assertions.*;

class WorkbookFormulaTest {
 static Map<String,Object> table(List<List<String>> rows,Map<String,String> formulas){var columns=new ArrayList<Map<String,Object>>();for(int i=0;i<rows.get(0).size();i++)columns.add(Map.of("id","c"+i,"label",SheetFormula.letter(i),"sourceHeader",SheetFormula.letter(i),"type","NUMBER","unit","","width",160));return new LinkedHashMap<>(Map.of("columns",columns,"rows",rows,"rowIds",java.util.stream.IntStream.range(0,rows.size()).mapToObj(i->"r"+i).toList(),"excel",Map.of("formulas",formulas)));}
 static Map<String,Object> book(Map<String,Object>... data){var sheets=new ArrayList<Map<String,Object>>();for(int i=0;i<data.length;i++)sheets.add(WorkbookRulesTest.entry("s"+i,"시트"+(i+1),data[i]));return WorkbookRulesTest.book(sheets);}
 static String value(Map<String,Object> b,String sheet,String ref){return ExcelCells.value(WorkbookRules.data(b,sheet),ref);}
 @Test void preservesAndRecalculatesAcrossSheetsAndExportsFormulas()throws Exception{
  var b=book(table(List.of(List.of("2","3","999")),Map.of("C2","SUM(A2:B2)")),table(List.of(List.of("999")),Map.of("A2","'시트1'!C2*2")));
  var first=WorkbookCalculation.calculate(b);assertThat(value(first,"s0","C2")).isEqualTo("5");assertThat(value(first,"s1","A2")).isEqualTo("10");
  var edit=ExcelCells.mutable(WorkbookRules.data(first,"s0"));ExcelCells.put(edit,"A2","7");var next=WorkbookCalculation.calculate(WorkbookRules.replace(first,"s0",edit));assertThat(value(next,"s1","A2")).isEqualTo("20");
  var exported=WorkbookRulesTest.reports(XlsxWriter.workbookBytes(next));assertThat(((Map<?,?>)exported.get(0).get("excel")).get("formulas").toString()).contains("SUM(A2:B2)");assertThat(exported.get(1).get("rows")).isEqualTo(List.of(List.of("20")));
 }
 @Test void sharedFormulasTranslateRelativeAndAbsoluteReferences()throws Exception{
  String xml="<row r='1'><c r='A1'><v>9</v></c></row><row r='2'><c r='A2'><v>3</v></c><c r='B2'><f t='shared' si='1' ref='B2:B3'>$A2+A$1</f><v>99</v></c></row><row r='3'><c r='A3'><v>8</v></c><c r='B3'><f t='shared' si='1'/><v>99</v></c></row>";
  var s=WorkbookRulesTest.reports(WorkbookRulesTest.fixture(List.of(xml),Map.of(),false)).get(0);assertThat(s.get("rows")).isEqualTo(List.of(List.of("3","12"),List.of("8","17")));assertThat(s.get("excel").toString()).contains("$A3+A$1");
 }
 @Test void emptyCachedFormulaCellsAreNotTrimmed()throws Exception{String xml="<row r='1'><c r='A1' t='inlineStr'><is><t>제목</t></is></c></row><row r='120'><c r='A120' t='str'><f>IF(1=1,&quot;&quot;,1)</f><v></v></c></row>";var s=WorkbookRulesTest.reports(WorkbookRulesTest.fixture(List.of(xml),Map.of(),false)).get(0);assertThat((List<?>)s.get("rows")).hasSize(119);assertThat(s.get("excel").toString()).contains("A120");}
 @Test void unsupportedRetainsCacheButDoesNotSilentlyPretendSuccess(){var b=book(table(List.of(List.of("25","99")),Map.of("A2","UNKNOWN_FN(1)","B2","A2*2")));var calculated=WorkbookCalculation.calculate(b);var data=WorkbookRules.data(calculated,"s0");assertThat(value(calculated,"s0","A2")).startsWith("#");assertThat(ExcelCells.<Map<String,Object>>map(ExcelCells.meta(data),"issues").get("A2")).containsEntry("cached","25");var repaired=WorkbookCalculation.repair(calculated,"repair");assertThat(value(repaired,"s0","A2")).isEqualTo("25");assertThat(value(repaired,"s0","B2")).isEqualTo("50");assertThat(ExcelCells.map(ExcelCells.meta(WorkbookRules.data(repaired,"s0")),"formulas")).containsKey("B2");assertThat(ExcelCells.map(ExcelCells.meta(WorkbookRules.data(repaired,"s0")),"paused")).containsKey("A2");var restored=WorkbookCalculation.repair(repaired,"restore");assertThat(ExcelCells.map(ExcelCells.meta(WorkbookRules.data(restored,"s0")),"formulas")).containsKey("A2");}
 @Test void invalidCacheClearsOnlyProblemOutputAndRetainsDependentFormula(){var b=book(table(List.of(List.of("0","#DIV/0!","#DIV/0!")),Map.of("B2","1/A2","C2","SUM(B2)")));var repaired=WorkbookCalculation.repair(b,"repair");assertThat(value(repaired,"s0","A2")).isEqualTo("0");assertThat(value(repaired,"s0","B2")).isEmpty();assertThat(value(repaired,"s0","C2")).isEqualTo("#N/A");assertThat(ExcelCells.map(ExcelCells.meta(WorkbookRules.data(repaired,"s0")),"formulas")).containsEntry("C2","SUM(B2)");}
 @Test void rootRepairDoesNotOverwriteValidInputs(){var b=book(table(List.of(List.of("3","4","#REF!")),Map.of("C2","#REF!+A2")));var fixed=WorkbookCalculation.repair(b,"repair");assertThat(value(fixed,"s0","A2")).isEqualTo("3");assertThat(value(fixed,"s0","B2")).isEqualTo("4");assertThat(value(fixed,"s0","C2")).isEmpty();}
 @Test void stringNumericAndDatesKeepNativeExcelSemantics(){var t=table(List.of(List.of("2026-01-05","3","cached","cached")),Map.of("C2","A2&\"\"","D2","SUM(B2)"));var cols=(List<Map<String,Object>>)t.get("columns");var next=new ArrayList<Map<String,Object>>();for(var c:cols){var n=new LinkedHashMap<>(c);n.put("type","TEXT");next.add(n);}t.put("columns",next);t.put("excel",Map.of("formulas",Map.of("C2","A2&\"\"","D2","SUM(B2)"),"values",Map.of("A2",List.of("46027","2026-01-05","n","yyyy-mm-dd"),"B2",List.of("3","3","s",""))));var b=WorkbookCalculation.calculate(book(t));assertThat(value(b,"s0","C2")).isEqualTo("46027");assertThat(value(b,"s0","D2")).isEqualTo("0");}
 @Test void cyclesAndExternalWorkbooksRemainExplicit(){var b=WorkbookCalculation.calculate(book(table(List.of(List.of("1","2","3")),Map.of("A2","B2","B2","A2","C2","'[other.xlsx]Sheet1'!A1"))));var issues=ExcelCells.map(ExcelCells.meta(WorkbookRules.data(b,"s0")),"issues");assertThat(issues).hasSize(3);assertThat(issues.toString()).contains("순환","외부");}
 @Test void structureMovesCellsAndReferencesAcrossSheets(){var b=book(table(List.of(List.of("2","3","5")),Map.of("C2","A2+B2")),table(List.of(List.of("5")),Map.of("A2","'시트1'!C2")));var moved=WorkbookStructure.apply(b,"s0",null,List.of("c2","c0","c1"),null,false);assertThat(value(moved,"s0","A2")).isEqualTo("5");assertThat(ExcelCells.map(ExcelCells.meta(WorkbookRules.data(moved,"s0")),"formulas")).containsEntry("A2","B2+C2");assertThat(value(moved,"s1","A2")).isEqualTo("5");var renamed=WorkbookStructure.apply(moved,"s0",null,null,"판매",false);assertThat(ExcelCells.map(ExcelCells.meta(WorkbookRules.data(renamed,"s1")),"formulas").toString()).contains("판매!");}
 @Test void deletingRowsShrinksSumAndDeletedDirectReferenceBecomesRefError(){var b=book(table(List.of(List.of("2","6","2"),List.of("4","","")),Map.of("B2","SUM(A2:A3)","C2","A3")));var n=WorkbookStructure.apply(b,"s0",List.of(0),null,null,false);assertThat(value(n,"s0","B2")).isEqualTo("2");assertThat(value(n,"s0","C2")).isEqualTo("#REF!");}
 @Test void deletingSheetInvalidatesCrossSheetReference(){var b=book(table(List.of(List.of("2")),Map.of()),table(List.of(List.of("2")),Map.of("A2","'시트1'!A2")));var n=WorkbookStructure.apply(b,"s0",null,null,null,true);assertThat(value(n,"s1","A2")).isEqualTo("#REF!");}
 @Test void aiRetainsOriginalFormulasAndCanProposeNewFormulaInScopedRows(){var t=table(List.of(List.of("2","4"),List.of("3","6")),Map.of("B2","A2*2","B3","A3*2"));var scope=Map.<String,Object>of("rowStart",2,"rowCount",1);var p=AiSheetScope.project(SheetRules.normalize(t),scope);assertThat(((List<List<String>>)p.get("rows")).get(0).get(1)).isEqualTo("=A3*2");var edited=new LinkedHashMap<>(p);edited.put("rows",List.of(List.of("5","=A3*3")));var proposal=SheetRules.normalize(ExcelCells.aiFormulas(edited,0));var merged=AiSheetScope.merge(SheetRules.normalize(t),proposal,scope);var b=WorkbookCalculation.calculate(book(merged));assertThat(value(b,"s0","B2")).isEqualTo("4");assertThat(value(b,"s0","B3")).isEqualTo("15");}
 @Test void formulasRequirePermissionAndTemplatesDoNotContainSourceFormulas(){var before=table(List.of(List.of("1")),Map.of());var after=table(List.of(List.of("1")),Map.of("A2","1+1"));assertThat(SheetRules.requiredActions(before,after)).contains("workspace.sheet.formula.update");assertThat(ExcelCells.meta(WorkbookRules.data(WorkbookRules.template(book(after)),"s0"))).isEmpty();}
 @Test void analysisSkipsErrorsAndProvisionalValues(){var b=WorkbookCalculation.repair(book(table(List.of(List.of("12"),List.of("5")),Map.of("A2","UNKNOWN_FN(1)"))),"repair");var result=SheetAnalysis.calculate(WorkbookRules.data(b,"s0"),Map.of("operation","SUM","valueColumn","c0"),1);assertThat(result.get("excludedFormulaValues")).isEqualTo(1);assertThat(result.get("points").toString()).contains("value=5");}

 @Test void nativeAndColumnFormulaCyclesCannotSilentlyReuseCachedValues(){var data=table(List.of(List.of("2","4")),Map.of("A2","B2*2"));var cols=new ArrayList<Map<String,Object>>((List<Map<String,Object>>)data.get("columns"));var c=new LinkedHashMap<>(cols.get(1));c.put("formula","[c0]*2");cols.set(1,c);data.put("columns",cols);var b=WorkbookCalculation.calculate(book(data));assertThat(value(b,"s0","A2")).isEqualTo("#CIRC!");assertThat(value(b,"s0","B2")).isEqualTo("#CIRC!");}
 @Test void arrayFormulaIsExplainedAndCacheCanBeUsedProvisionally()throws Exception{var xml="<row r='1'><c r='A1'><v>4</v></c></row><row r='2'><c r='A2'><f t='array' ref='A2:A2'>SUM(A1*2)</f><v>8</v></c></row>";var r=WorkbookRulesTest.reports(WorkbookRulesTest.fixture(List.of(xml),Map.of(),false)).get(0);assertThat(r.get("excel").toString()).contains("배열", "UNSUPPORTED", "cached=8");}
 @Test void noncontiguousRangeMoveIsRejectedRatherThanChangingSumMeaning(){var b=book(table(List.of(List.of("1","2","3","3")),Map.of("D2","SUM(A2:B2)")));assertThatThrownBy(()->WorkbookStructure.apply(b,"s0",null,List.of("c0","c2","c1","c3"),null,false)).isInstanceOf(Problem.class).hasMessageContaining("안전하게");}
 @Test void dynamicReferenceKeepsFormulaAndExcludesProvisionalResult(){var b=book(table(List.of(List.of("12","24")),Map.of("A2","UNKNOWN_FN(1)","B2","INDIRECT(\"A2\")*2")));var repaired=WorkbookCalculation.repair(b,"repair");var d=WorkbookRules.data(repaired,"s0");assertThat(ExcelCells.map(ExcelCells.meta(d),"formulas")).containsKey("B2");assertThat(ExcelCells.<Map<String,Object>>map(ExcelCells.meta(d),"issues").get("B2").get("code")).isEqualTo("TEMPORARY_DEPENDENCY");}
 @Test void mixedDateSystemsNeverProduceSilentCrossSheetDates(){var a=table(List.of(List.of("100")),Map.of());a.put("excel",Map.of("date1904",true));var b=table(List.of(List.of("100")),Map.of("A2","'시트1'!A2"));var calculated=WorkbookCalculation.calculate(book(a,b));assertThat(ExcelCells.map(ExcelCells.meta(WorkbookRules.data(calculated,"s1")),"issues").toString()).contains("날짜 체계");}
}
